  'GNL Solution peut refuser l\'accès au Site à tout Utilisateur qui ne respecte pas les présentes CGU.' => 'GNL Solution may refuse access to the Site to any User who does not comply with these Terms.',
  '<x1>{0}.</x1>Accès au site' => '<x1>{0}.</x1>Access to the site',
